-- Reproduce the trace_id and root span_id generated by load.sql for one
-- global trace index. Used to pick a known trace for the lookup benchmark.
SELECT
    lower(concat(
        leftPad(hex(cityHash64({trace_index:UInt64}, 1)), 16, '0'),
        leftPad(hex(cityHash64({trace_index:UInt64}, 2)), 16, '0')
    )) AS trace_id,
    lower(leftPad(hex(cityHash64({trace_index:UInt64}, 0, 3)), 16, '0')) AS root_span_id;
